class Solution { public: int kInversePairs(int n,int k){const long long mod=1000000007;vector<long long> previous(k+1);previous[0]=1;for(int length=1;length<=n;++length){vector<long long> current(k+1);long long window=0;for(int inversions=0;inversions<=k;++inversions){window=(window+previous[inversions])%mod;if(inversions>=length)window=(window-previous[inversions-length]+mod)%mod;current[inversions]=window;}previous.swap(current);}return previous[k];} };
